import json,re,pathlib
root=pathlib.Path('/Users/olivier/Projects/enterprise-workflow');out=root/'graphify-out';a=json.loads((out/'semantic_assignment_0.json').read_text())
def stem(p):return re.sub('[^a-z0-9_]','_',str(pathlib.Path(p).relative_to(root).with_suffix('')).replace('/','_').lower())
def norm(s):return re.sub('[^a-z0-9_]','_',s.lower())
def blank():return dict(nodes=[],edges=[],hyperedges=[],input_tokens=0,output_tokens=0)
def node(g,p,key,label,typ='rationale',rationale=None):
 n=dict(id=stem(p)+'_'+norm(key),label=label,file_type=typ,source_file=p,source_location=None,source_url=None,captured_at=None,author=None,contributor=None)
 if rationale:n['rationale']=rationale
 if not any(x['id']==n['id'] for x in g['nodes']):g['nodes'].append(n)
 return n['id']
def edge(g,p,s,t,rel='references',confidence='EXTRACTED',score=1.):g['edges'].append(dict(source=s,target=t,relation=rel,confidence=confidence,confidence_score=score,source_file=p,source_location=None,weight=1.))
