g=blank();docs={};cmap={}
for p,cs in zip(a['documents'],concepts):
 text=pathlib.Path(p).read_text();title=next((x.lstrip('# ').strip() for x in text.splitlines() if x.startswith('# ')), 'Cross-platform CI workflow')
 did=node(g,p,'document',title,'document');docs[p]=did
 for k,label,why in cs:
  nid=node(g,p,k,label,rationale=why);edge(g,p,did,nid);cmap[(pathlib.Path(p).name,k)]=nid
# Explicit markdown citations and paths, retaining originating source metadata.
for p in a['documents']:
 text=pathlib.Path(p).read_text()
 for target in dict.fromkeys(re.findall(r'\[[^\]]+\]\(([^)]+)\)',text)):
  if target.startswith('http'):
   rid=node(g,p,'citation_'+norm(target),target,'document');g['nodes'][-1]['source_url']=target;edge(g,p,docs[p],rid,'cites');continue
  dest=str((pathlib.Path(p).parent/target.split('#')[0]).resolve())
  rid=docs.get(dest)
  if not rid:
   # Node originates from the citing document; referenced target is retained as an attribute.
   rid=node(g,p,'reference_'+norm(target),pathlib.Path(target).name,'document');g['nodes'][-1]['referenced_path']=dest
  edge(g,p,docs[p],rid)
# Cross-cutting semantics based on distinct mechanisms, not merely repeated vocabulary.
def cross(f,k,f2,k2,rel='conceptually_related_to',conf='INFERRED',score=.85):
 p=next(p for p in a['documents'] if pathlib.Path(p).name==f);edge(g,p,cmap[(f,k)],cmap[(f2,k2)],rel,conf,score)
cross('0017-designation-approbateur.md','designated_approver','0019-workflow-stages.md','exact_grants','references','EXTRACTED',1.)
cross('0018-ldap-generique.md','stable_subject','0016-securite-profils-l5.md','stable_identity','implements','EXTRACTED',1.)
cross('0015-worker-retry-outbox-l4b.md','outbox','0008-durabilite.md','outbox','implements','INFERRED',.95)
cross('0020-attentes-metier-l6.md','idempotent_receipt','0013-contrats-l2.md','canonical_contracts','conceptually_related_to','INFERRED',.75)
cross('0022-loader-definitif-et-migrations-etat-l7b.md','state_migration','0015-worker-retry-outbox-l4b.md','outbox','semantically_similar_to','INFERRED',.75)
# Both execute user code outside SQL then conditionally persist durable intent/results; state migration is effect-free.
for file,keys,label in [('0019-workflow-stages.md',['stage','exact_grants','assignment_modes','separate_read'],'Exact stage action access control'),('0022-loader-definitif-et-migrations-etat-l7b.md',['state_migration','artifact_inventory','reconcile','maintenance_store'],'Safe exact-artifact state evolution')]:
 p=next(p for p in a['documents'] if pathlib.Path(p).name==file)
 g['hyperedges'].append(dict(id=stem(p)+'_flow',label=label,nodes=[cmap[(file,k)] for k in keys],relation='participate_in',confidence='EXTRACTED',confidence_score=1.,source_file=p))
(out/'.graphify_chunk_0_docs.json').write_text(json.dumps(g,ensure_ascii=False,indent=2))
